package com.project.KafkaPackage;

import java.sql.*;
import java.util.Properties;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;

public class GetDataFromMySQL {
    private static final String TOPIC = "MySQLStoreData";
    private static final String BOOTSTRAP_SERVERS = "localhost:9092";

    private static Producer<String, String> createProducer() {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, BOOTSTRAP_SERVERS);
        props.put(ProducerConfig.CLIENT_ID_CONFIG, "MySQLToKafka");
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        return new KafkaProducer<>(props);
    }

    public static void runProducer() throws Exception {
        Producer<String, String> producer = createProducer();
        Connection connection = DriverManager.getConnection("jdbc:mysql://localhost/YouBuyy?user=root&password=Infy@123");
        Statement stmt = connection.createStatement();
        ResultSet rs = stmt.executeQuery("SELECT * FROM YouBuyy.StoreData");

        while (rs.next()) {
            ProducerRecord<String, String> record = new ProducerRecord<>(TOPIC, rs.getString(1), rs.getString(2));
            RecordMetadata metadata = producer.send(record).get();
            System.out.println("Offset: " + metadata.offset() + " Partition: " + metadata.partition());
        }
    }

    public static void main(String[] args) throws Exception {
        try {
            runProducer();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}

